import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String emailInput = scanner.next();
        int len = emailInput.length();
        StringBuilder emailBuilder = new StringBuilder(emailInput);

        for (int idx = 1; idx + 1 < len; ++idx) {
            if (emailBuilder.charAt(idx) == 'a' && emailBuilder.charAt(idx + 1) == 't') {
                emailBuilder.setCharAt(idx, '@');
                break;
            }
        }

        for (int idx = 1; idx + 2 < len; ++idx) {
            if (emailBuilder.charAt(idx) == 'd' && emailBuilder.charAt(idx + 1) == 'o' && emailBuilder.charAt(idx + 2) == 't') {
                emailBuilder.setCharAt(idx, '.');
            }
        }

        int i = 0;
        while (i < len) {
            char ch = emailBuilder.charAt(i);
            if (ch == '@') {
                System.out.print('@');
                i++;
            } else if (ch == '.') {
                System.out.print('.');
                i += 3;
            } else {
                System.out.print(ch);
                i++;
            }
        }
        System.out.println();
        scanner.close();
    }
}
